{
  "findings": [
    {
      "ref": "[D533]",
      "area": "contact",
      "claim": "A parent reports that children under 13 are automatically blocked from direct chat with specific players unless a verified parent changes settings.",
      "stance": "risk",
      "quote": "Children under 13 are allowed by default to engage in public text chat with others joining the same experience (“Experience Chat”). However, they’re automatically blocked from chatting directly with specific players of that or other games on Roblox (“Experience Direct Chat” or “Whisper Chat”), unless a verified parent changes those settings."
    },
    {
      "ref": "[D533]",
      "area": "money",
      "claim": "A parent reports that Roblox offers in-app purchases of Robux, with the smallest purchase being 400 Robux for $4.99.",
      "stance": "risk",
      "quote": "The smallest amount you can purchase is 400 Robux for $4.99."
    },
    {
      "ref": "[D533]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal information for age verification and may share data with third parties.",
      "stance": "risk",
      "quote": "Users are free to opt-out of using facial age estimation if they are not comfortable, though Roblox does say that no information is saved or stored. Users can verify their age using ID verification instead."
    },
    {
      "ref": "[D533]",
      "area": "age_gating",
      "claim": "A parent reports that users under 9 are automatically barred from accessing \"Moderate\" content, though they can access \"Minimal\" or \"Mild\" content.",
      "stance": "mitigation",
      "quote": "Note that for users under the age of 9 are automatically barred from accessing “Moderate” content (though they can freely access content labeled as “Minimal” or “Mild”)."
    },
    {
      "ref": "[D533]",
      "area": "content",
      "claim": "A parent reports that some Roblox experiences are labeled \"Restricted\" and require age verification for 17+ users.",
      "stance": "risk",
      "quote": "These experiences are only available to 17+ users who verified their ages by completing ID verification."
    },
    {
      "ref": "[D533]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny for data collection practices.",
      "stance": "risk",
      "quote": "Roblox also claims that players under 13 have their posts and chats filtered both for inappropriate content and to prevent personal information from being posted."
    }
  ]
}
